"use client";

/**
 * New PIN, from the admin's own menu (Kian's ruling of 2026-10-13, evening:
 * PINs are generated by Nubnb, never chosen; New PIN replaces yours with
 * another random one, shown once). The current PIN comes first, in masked
 * boxes, so a session alone cannot become a PIN; a wrong one counts toward
 * this connection's lock. Then the new PIN, shown once. Every other session
 * the admin holds ends; this one carries on with a new cookie.
 */

import { useEffect, useRef, useState } from "react";
import { Dialog } from "../property/editor/controls";
import ed from "../property/editor/editor.module.css";
import gate from "./PinGate.module.css";
import { PinBoxes } from "./PinBoxes";
import { PinReveal } from "./PinReveal";
import { lockTimeWords, renewOwnPin } from "@/app/lib/admins-client";
import { PIN_LENGTH, SIGN_IN_PIN_PATTERN, type SignedInAdminView } from "@/app/lib/admins/model";

interface Props {
  admin: SignedInAdminView;
  onRenewed: (admin: SignedInAdminView) => void;
  onClose: () => void;
}

export function NewPinDialog({ admin, onRenewed, onClose }: Props) {
  const [current, setCurrent] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  /** The new PIN while this dialog shows it; dropped when it closes. */
  const [shown, setShown] = useState<{ pin: string; admin: SignedInAdminView } | null>(null);
  const firstBox = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    const timer = setTimeout(() => firstBox.current?.focus(), 50);
    return () => clearTimeout(timer);
  }, []);

  const ready = SIGN_IN_PIN_PATTERN.test(current) && !busy;

  const go = async () => {
    if (!ready) return;
    setBusy(true);
    setError(null);
    const result = await renewOwnPin(current);
    setBusy(false);
    setCurrent("");
    if (result.ok) {
      setShown({ pin: result.data.newPin, admin: result.data.admin });
      return;
    }
    if (result.status === 429 && result.lockedUntil) setError(`Locked until ${lockTimeWords(result.lockedUntil)}.`);
    else if (result.code === "ADMIN_CURRENT_PIN_WRONG") setError(result.hint?.startsWith("One more") ? "That is not your current PIN. One more wrong PIN locks sign-in from here for 15 minutes." : "That is not your current PIN.");
    else setError(result.unknown ? `${result.title} It may or may not have changed.` : result.title);
  };

  if (shown) {
    const done = () => {
      onRenewed(shown.admin);
      onClose();
    };
    return (
      <Dialog
        title="Your new PIN"
        onClose={done}
        dismissible={false}
        actions={
          <button type="button" className={`${ed.btn} ${ed.btnPrimary}`} onClick={done}>
            I have noted it
          </button>
        }
      >
        <PinReveal pin={shown.pin} label="Your new PIN">
          <p>Your old PIN no longer works. Any other device signed in as {admin.name} is signed out.</p>
        </PinReveal>
      </Dialog>
    );
  }

  return (
    <Dialog
      title="New PIN"
      onClose={onClose}
      initialFocus="none"
      actions={
        <>
          <button type="button" className={`${ed.btn} ${ed.btnGhost}`} onClick={onClose} disabled={busy}>
            Cancel
          </button>
          <button type="submit" form="new-pin" className={`${ed.btn} ${ed.btnPrimary}`} disabled={!ready}>
            {busy ? "Getting it…" : "Get a new PIN"}
          </button>
        </>
      }
    >
      <form
        id="new-pin"
        className={gate.pinForm}
        onSubmit={(e) => {
          e.preventDefault();
          void go();
        }}
      >
        <div className={gate.field}>
          <span className={gate.fieldLabel}>{admin.pin === "shared" ? "Current PIN (the shared one)" : "Current PIN"}</span>
          <PinBoxes length={PIN_LENGTH} value={current} onChange={(v) => { setCurrent(v); setError(null); }} onEnter={() => void go()} disabled={busy} label="Current PIN" compact firstRef={(el) => { firstBox.current = el; }} />
        </div>
        {error && (
          <span className={gate.errorText} role="alert">
            {error}
          </span>
        )}
      </form>
    </Dialog>
  );
}
